Lemma annU_window_facts u u' : 0 <= u -> 0 <= u' -> u <> u' ->
  annU_lo u u' <= annU_plo u u' /\ annU_phi u u' <= annU_hi u u' /\ annU_plo u u' <= annU_phi u u'
  /\ (u' mod 8 <> 0 -> annU_lo u u' <= u' / 8 < annU_hi u u')
